import urllib.request, json, xml.etree.ElementTree as ET, html
from datetime import datetime
# parse weather summary
url='https://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.0060&current=temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m&hourly=temperature_2m,precipitation_probability,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,sunrise,sunset&temperature_unit=fahrenheit&wind_speed_unit=mph&precipitation_unit=inch&timezone=America%2FNew_York'
data=json.load(urllib.request.urlopen(url,timeout=20))
print('WEATHER_SUMMARY')
print(json.dumps({
 'current':data['current'],
 'daily_today':{k:data['daily'][k][0] for k in data['daily'] if k!='time'},
 'today_hours':[(t,p,temp,w) for t,p,temp,w in zip(data['hourly']['time'][:24],data['hourly']['precipitation_probability'][:24],data['hourly']['temperature_2m'][:24],data['hourly']['weather_code'][:24])][8:22]
}, indent=2))
# rss titles
def rss(url):
 req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
 root=ET.fromstring(urllib.request.urlopen(req,timeout=20).read())
 ch=root.find('channel')
 print('\nRSS',ch.findtext('title'),ch.findtext('lastBuildDate') or ch.findtext('pubDate'))
 for item in ch.findall('item')[:8]:
  print('-', html.unescape(item.findtext('title') or ''), '|', html.unescape(item.findtext('description') or '')[:180], '|', item.findtext('pubDate'))
for u in ['https://feeds.content.dowjones.io/public/rss/mw_topstories','https://www.cnbc.com/id/100003114/device/rss/rss.html','https://finance.yahoo.com/news/rssindex']:
 try: rss(u)
 except Exception as e: print('RSS_ERR',u,e)
